<script setup lang="ts">import{ref}from"vue";import{useRouter}from"vue-router";import BasePageHeader from"@/components/base/BasePageHeader.vue";import VodForm from"@/features/vod/components/VodForm.vue";import type{VodFormData}from"@/domain/vod/models";import{mapVodFormToPayload}from"@/domain/vod/mapper";import{availabilityRepository}from"@/domain/repositories";const router=useRouter(),saving=ref(false),error=ref("");async function save(f:VodFormData){saving.value=true;error.value="";try{await availabilityRepository.create(mapVodFormToPayload(f));await router.push({name:"vod",query:{created:"1"}})}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{saving.value=false}}</script><template><BasePageHeader eyebrow="VOD" title="Adicionar disponibilidade" description="Regista onde e em que condições um título está disponível."/><div v-if="error" class="form-alert form-alert-error">{{error}}</div><VodForm :saving="saving" @submit="save"/></template>
